window.receiveProjectSource({"path": "src/microservices/web_extraction/services/helpers/layer_two.py", "lines": ["\"\"\"Helpers for layer-two processing: embeddings, deduplication and article writes.\"\"\"", "", "from collections import defaultdict", "from dataclasses import dataclass, field", "from datetime import datetime", "from enum import Enum", "from http import HTTPMethod", "from typing import Any, Dict, List, Optional, Tuple", "from uuid import UUID", "", "import numpy as np", "from aiohttp import ClientTimeout", "from sqlalchemy import case, func, select, text", "from sqlalchemy.dialects.postgresql import insert", "from sqlalchemy.ext.asyncio import AsyncSession", "", "from common.config.config_base import config as config", "from common.exceptions.exceptions import (", "    AIServiceException,", "    DatabaseCommitException,", "    DatabaseReadException,", "    DatabaseWriteException,", ")", "from common.helpers.publication_date import as_utc", "from common.models.enums import ServiceLayer", "from common.models.enums.article_type import ArticleType", "from common.services.api_helper import APIHelper", "from common.utils.url_helpers import normalize_url", "from common.utils.well_known_data import (", "    MICROSERVICES_DATA as data,", ")", "from microservices.web_extraction.config import (", "    config as web_config,", ")", "from microservices.web_extraction.exceptions import WebExtractionDataError", "from microservices.web_extraction.logging import logger", "from microservices.web_extraction.models import (", "    Article,", "    ArticleChunk,", "    DuplicatedArticle,", "    WebExtractionResponse,", "    ZyteArticle,", ")", "from microservices.web_extraction.schemas.article_base_schemas import (", "    ArticleSchema,", ")", "from microservices.web_extraction.schemas.embedding import ChunkEmbedding, ChunkVectors", "", "from .common import upsert_article_chunks", "from .landing_page import is_article_permalink", "", "EMBED_CHUNKS_TIMEOUT = ClientTimeout(", "    total=web_config.EMBED_TOTAL_TIMEOUT_LIMIT,", "    connect=web_config.EMBED_CONNECT_TIMEOUT_LIMIT,", "    sock_connect=web_config.EMBED_SOCK_CONNECT_TIMEOUT_LIMIT,", "    sock_read=web_config.EMBED_SOCK_READ_TIMEOUT_LIMIT,", ")", "", "", "def _unit_normalize(vec: np.ndarray) -> np.ndarray:", "    \"\"\"L2-normalize ``vec`` so its dot product with another unit vector is a true cosine.", "", "    Stored embeddings come from a ``Vector(3072)`` float32 column and are only", "    approximately unit-norm; normalizing both operands at the scoring site is what", "    makes ``np.dot(a, b)`` equal ``cos(a, b)`` rather than ``\u2248 cos(a, b)``.", "", "    :param vec: Embedding vector to normalize. Expected to be finite; a zero", "        vector is returned unchanged (its dot with anything is 0, which the", "        ``DEDUP_FLOOR_THRESHOLD`` filter then drops).", "    :type vec: np.ndarray", "", "    :returns: Unit-norm vector, or the original zero vector if ``norm == 0``.", "    :rtype: np.ndarray", "    \"\"\"", "    norm = np.linalg.norm(vec)", "    if norm == 0:", "        return vec", "    return vec / norm", "", "", "async def embed_article_chunks(", "    api_helper: APIHelper, article_text: str, activity_id: UUID, layer: ServiceLayer", ") -> ChunkVectors:", "    \"\"\"Embeds article text chunks into vectors using the accelerate AI service,", "    and validate the response into the ChunkVectors schema.", "", "    :param api_helper: The API helper to use for making requests.", "    :type api_helper: APIHelper", "    :param article_text: The article text to be embedded.", "    :type article_text: str", "    :param activity_id: The activity ID for logging purposes.", "    :type activity_id: UUID", "    :param layer: The service layer for logging purposes.", "    :type layer: ServiceLayer", "", "    :returns: The chunk vectors containing embeddings and text.", "    :rtype: ChunkVectors", "", "    :raises AIServiceException: If there is an error during the embedding process or response validation.", "    \"\"\"", "    # 1). prepare request", "    headers = {", "        \"Content-Type\": \"application/json\",", "        \"x-microservice-id\": data.get(\"web_extraction\", {}).get(\"id\"),", "    }", "    method = HTTPMethod.POST", "    api_url = f\"{config.require_accelerate_alb_address()}{web_config.EMBED_CHUNKS_ENDPOINT}\"", "    payload = {", "        \"content\": article_text,", "    }", "", "    # 2). execute request", "    try:", "        content, _, _ = await api_helper.execute_api_request(", "            api_url,", "            method,", "            payload,", "            headers=headers,", "            timeout=EMBED_CHUNKS_TIMEOUT,", "        )", "        if isinstance(content, dict):", "            embedding_response = content", "        else:", "            raise AIServiceException(", "                f\"Unexpected response format from AI service; expected dict, got {type(content)}\",", "                endpoint=api_url,", "            )", "    except Exception as e:", "        raise AIServiceException(", "            f\"Failed to retrieve article chunk embeddings (caused by >>> {e!r})\",", "            endpoint=api_url,", "        ) from e", "", "    # 3). validate response", "    try:", "        chunk_vectors = ChunkVectors.model_validate(embedding_response)", "    except Exception as e:", "        raise AIServiceException(", "            f\"Failed to validate chunk vectors from AI service response (caused by >>> {e!r})\",", "            endpoint=api_url,", "            response=embedding_response,", "        ) from e", "", "    logger.info(", "        \"Embedded text into chunk vectors\",", "        chunk_count=len(chunk_vectors.chunks),", "        activity_id=str(activity_id),", "    )", "", "    return chunk_vectors", "", "", "class DeduplicationClassification(str, Enum):", "    \"\"\"3-tier article deduplication classification.\"\"\"", "", "    DUPLICATE = \"duplicate\"", "    SYNDICATION_CANDIDATE = \"syndication_candidate\"", "    UNIQUE = \"unique\"", "", "", "@dataclass(frozen=True)", "class CandidateMatch:", "    \"\"\"One vector-ANN-surfaced candidate article and its best matched chunk.", "", "    Surfaced from ``deduplicate_article`` (via ``DeduplicationResult.candidates``)", "    so post-dedup chain steps \u2014 the title/headline blocking key \u2014 can compare", "    titles and set ``best_match`` for a promotion WITHOUT re-running the HNSW", "    query. ``best_chunk`` is the candidate's highest-similarity matched", "    ``ArticleChunk``; ``best_similarity`` is that chunk's cosine score.", "", "    :param article_id: The candidate article's id.", "    :type article_id: UUID", "    :param best_similarity: Highest per-chunk cosine similarity to the incoming", "        article across this candidate's matched chunks.", "    :type best_similarity: float", "    :param best_chunk: The candidate ``ArticleChunk`` carrying ``best_similarity``.", "    :type best_chunk: ArticleChunk", "    \"\"\"", "", "    article_id: UUID", "    best_similarity: float", "    best_chunk: ArticleChunk", "", "", "@dataclass", "class DeduplicationResult:", "    \"\"\"Result of article-level deduplication with 3-tier classification.", "", "    Invariant: ``best_match`` is set iff ``classification != UNIQUE``. Both", "    DUPLICATE and SYNDICATION_CANDIDATE populate ``best_match`` so callers", "    (e.g. L2's syndication grouper) can attach via ``best_match.article_id``", "    without re-deriving it from candidates. UNIQUE always has", "    ``best_match = None`` and ``match_info = {}``. Enforced in", "    ``__post_init__``.", "", "    ``candidates`` is informational and does NOT participate in the", "    best-match-iff-not-UNIQUE invariant: it carries every ANN-surfaced", "    candidate (even for a UNIQUE result) so a downstream chain step can apply", "    the title/headline blocking key without a second HNSW round-trip.", "", "    Two scores are reported because they answer different questions, and the", "    absolute-count syndication signal can retarget ``best_match`` to a candidate", "    other than the highest-scored one:", "", "    - ``article_score`` always describes the HIGHEST-SCORED candidate. It is the", "      band-selection input and gates the borderline verifier's margin check, so", "      it stays on the top candidate even after a retarget.", "    - ``matched_article_score`` describes the candidate ``best_match`` actually", "      points at, and is what callers persist as the match's similarity. ``None``", "      for UNIQUE. Equal to ``article_score`` whenever no retarget happened.", "", "    Both are also recorded under ``match_info['syndication_signal']`` when the", "    signal fires, so a retargeted row's provenance is recoverable from the", "    persisted record alone.", "    \"\"\"", "", "    classification: DeduplicationClassification", "    best_match: Optional[ArticleChunk]", "    article_score: float", "    match_info: Dict[str, Any]", "    classification_method: str = \"vector-article-aggregate\"", "    candidates: List[CandidateMatch] = field(default_factory=list)", "    matched_article_score: Optional[float] = None", "", "    def __post_init__(self) -> None:", "        is_matched = self.classification != DeduplicationClassification.UNIQUE", "        has_match = self.best_match is not None", "        if is_matched != has_match:", "            raise ValueError(", "                f\"DeduplicationResult invariant violated: classification=\"", "                f\"{self.classification.value} but best_match is \"", "                f\"{'set' if has_match else 'None'}\"", "            )", "", "", "def _build_candidates_map(", "    match_sources: Dict[UUID, List[Tuple[int, np.ndarray, str]]],", "    matched_chunks_map: Dict[UUID, ArticleChunk],", ") -> Dict[UUID, Dict[int, Tuple[float, ArticleChunk]]]:", "    \"\"\"Score each matched chunk and group results by article_id.", "", "    For each matched chunk, computes cosine similarity against the incoming", "    embedding. Matches below ``DEDUP_FLOOR_THRESHOLD`` are discarded. For each", "    candidate article, only the best similarity per incoming chunk index is kept.", "", "    Incoming embeddings are expected to already be unit-norm ``np.ndarray`` values", "    (converted and L2-normalized once per incoming chunk by the caller) so the inner", "    loop does no redundant list\u2192array conversion and no re-normalization per candidate.", "", "    :param match_sources: Map of matched chunk ID to list of", "        ``(incoming_chunk_index, incoming_embedding, incoming_text)`` tuples.", "    :type match_sources: Dict[UUID, List[Tuple[int, np.ndarray, str]]]", "    :param matched_chunks_map: Map of chunk ID to loaded ``ArticleChunk`` rows.", "    :type matched_chunks_map: Dict[UUID, ArticleChunk]", "", "    :returns: ``Dict[article_id, Dict[incoming_chunk_index, (similarity, ArticleChunk)]]``.", "    :rtype: Dict[UUID, Dict[int, Tuple[float, ArticleChunk]]]", "    \"\"\"", "    candidates_map: Dict[UUID, Dict[int, Tuple[float, ArticleChunk]]] = defaultdict(dict)", "", "    for chunk_id, sources in match_sources.items():", "        matched_chunk = matched_chunks_map.get(chunk_id)", "        if matched_chunk is None:", "            continue", "", "        # Stored float32 vectors from pgvector are only approximately unit-norm,", "        # so an unnormalized dot can overshoot 1.0 by a few ULPs and break the", "        # bounded-cosine contract that downstream persistence and consumers", "        # assume. Normalize the matched operand once per chunk and clamp the", "        # per-chunk score into the valid cosine range. The same caveat applies", "        # if a future code path truncates embeddings via the OpenAI", "        # ``dimensions`` API parameter \u2014 those vectors are also not unit-norm.", "        matched_vec = _unit_normalize(np.asarray(matched_chunk.embedding, dtype=float))", "        for incoming_idx, incoming_embedding, _incoming_text in sources:", "            similarity = float(np.clip(np.dot(matched_vec, incoming_embedding), 0.0, 1.0))", "", "            if similarity < web_config.DEDUP_FLOOR_THRESHOLD:", "                continue", "", "            article_id = matched_chunk.article_id", "            current_best = candidates_map[article_id].get(incoming_idx)", "            if current_best is None or similarity > current_best[0]:", "                candidates_map[article_id][incoming_idx] = (similarity, matched_chunk)", "", "    return candidates_map", "", "", "def _high_sim_matched_chunk_count(", "    chunk_matches: Dict[int, Tuple[float, ArticleChunk]], similarity_bar: float", ") -> int:", "    \"\"\"Count DISTINCT existing chunks matched at or above ``similarity_bar``.", "", "    Distinct existing chunks \u2014 keyed by ``ArticleChunk.id``, not incoming-chunk", "    index \u2014 so a short incoming article whose several chunks all match one", "    boilerplate paragraph counts as a single match, preserving the short-article", "    false-DUPLICATE guard.", "", "    :param chunk_matches: One candidate's ``{incoming_chunk_index: (similarity,", "        ArticleChunk)}`` best-match map.", "    :type chunk_matches: Dict[int, Tuple[float, ArticleChunk]]", "    :param similarity_bar: Minimum per-chunk cosine similarity to count.", "    :type similarity_bar: float", "    :returns: Number of distinct existing chunks matched at/above the bar.", "    :rtype: int", "    \"\"\"", "    return len(", "        {", "            matched_chunk.id", "            for similarity, matched_chunk in chunk_matches.values()", "            if similarity >= similarity_bar", "        }", "    )", "", "", "def _select_syndication_signal_winner(", "    candidates_map: Dict[UUID, Dict[int, Tuple[float, ArticleChunk]]],", "    article_scores: Dict[UUID, float],", ") -> Optional[Tuple[UUID, int]]:", "    \"\"\"Pick the candidate that fires the absolute-count high-similarity signal.", "", "    Scans EVERY candidate, not just the top-scored one: the diluted", "    ``article_score`` can rank a chrome-heavy candidate first while a lower-scored", "    candidate carries the qualifying count of near-verbatim chunk matches. Counts", "    distinct existing chunks matched at/above", "    ``DEDUP_SYNDICATION_SIGNAL_SIMILARITY`` per candidate, keeps those meeting", "    ``DEDUP_SYNDICATION_SIGNAL_MIN_CHUNKS``, and returns a deterministic winner", "    (highest count, then highest score, then smallest UUID).", "    ``DEDUP_SYNDICATION_SIGNAL_MIN_CHUNKS == 0`` disables the signal (kill switch).", "", "    The winner's high-similarity count is returned alongside its id so the caller", "    can record it without recomputing the per-candidate traversal.", "", "    :param candidates_map: Per-article best-per-incoming-chunk matches.", "    :type candidates_map: Dict[UUID, Dict[int, Tuple[float, ArticleChunk]]]", "    :param article_scores: Per-article composite scores (used only for tie-break).", "    :type article_scores: Dict[UUID, float]", "    :returns: ``(winning article_id, its distinct high-similarity matched-chunk", "        count)``, or ``None`` when the signal is disabled or no candidate", "        qualifies.", "    :rtype: Optional[Tuple[UUID, int]]", "    \"\"\"", "    min_chunks = web_config.DEDUP_SYNDICATION_SIGNAL_MIN_CHUNKS", "    if min_chunks <= 0:", "        return None", "", "    similarity_bar = web_config.DEDUP_SYNDICATION_SIGNAL_SIMILARITY", "    qualifying: List[Tuple[int, float, UUID]] = []", "    for article_id, chunk_matches in candidates_map.items():", "        high_sim_count = _high_sim_matched_chunk_count(chunk_matches, similarity_bar)", "        if high_sim_count >= min_chunks:", "            qualifying.append((high_sim_count, article_scores.get(article_id, 0.0), article_id))", "", "    if not qualifying:", "        return None", "", "    # Deterministic winner: max count, then max score, then smallest UUID. Negate", "    # count/score so ``min`` prefers the larger of each; ``UUID.int`` breaks ties.", "    winner = min(qualifying, key=lambda item: (-item[0], -item[1], item[2].int))", "    return winner[2], winner[0]", "", "", "def _build_candidate_matches(", "    candidates_map: Dict[UUID, Dict[int, Tuple[float, ArticleChunk]]],", ") -> List[CandidateMatch]:", "    \"\"\"Collapse each candidate's per-incoming-chunk matches to its single best chunk.", "", "    Produces the ``DeduplicationResult.candidates`` list: one ``CandidateMatch``", "    per candidate article, carrying its highest-similarity matched chunk. The", "    title/headline blocking key uses ``best_chunk`` to set ``best_match`` on a", "    promotion without re-querying the vector index.", "", "    :param candidates_map: Per-article best-per-incoming-chunk matches.", "    :type candidates_map: Dict[UUID, Dict[int, Tuple[float, ArticleChunk]]]", "    :returns: One ``CandidateMatch`` per candidate article.", "    :rtype: List[CandidateMatch]", "    \"\"\"", "    matches: List[CandidateMatch] = []", "    for article_id, chunk_matches in candidates_map.items():", "        best_similarity, best_chunk = max(chunk_matches.values(), key=lambda item: item[0])", "        matches.append(", "            CandidateMatch(", "                article_id=article_id,", "                best_similarity=best_similarity,", "                best_chunk=best_chunk,", "            )", "        )", "    return matches", "", "", "def _build_dedup_result(", "    candidates_map: Dict[UUID, Dict[int, Tuple[float, ArticleChunk]]],", "    article_scores: Dict[UUID, float],", "    chunks: List[ChunkEmbedding],", ") -> DeduplicationResult:", "    \"\"\"Classify the best candidate and build the final DeduplicationResult.", "", "    Selects the candidate article with the highest composite score, applies", "    threshold-based 3-tier classification, and populates ``best_match`` /", "    ``match_info`` for any matched classification.", "", "    :param candidates_map: Map of article_id to per-incoming-chunk best matches,", "        structured as ``Dict[article_id, Dict[incoming_chunk_index, (similarity, ArticleChunk)]]``.", "    :type candidates_map: Dict[UUID, Dict[int, Tuple[float, ArticleChunk]]]", "    :param article_scores: Map of article_id to composite", "        ``coverage * avg_similarity`` score, where coverage is symmetric", "        (``matched_chunks / max(incoming_total, existing_total)``).", "    :type article_scores: Dict[UUID, float]", "    :param chunks: The incoming ``ChunkEmbedding`` objects (used to populate match_info text).", "    :type chunks: List[ChunkEmbedding]", "", "    :returns: A DeduplicationResult with classification, score, best match, and match info.", "    :rtype: DeduplicationResult", "    \"\"\"", "    candidates = _build_candidate_matches(candidates_map)", "", "    if not article_scores:", "        return DeduplicationResult(", "            classification=DeduplicationClassification.UNIQUE,", "            best_match=None,", "            article_score=0.0,", "            match_info={},", "            candidates=candidates,", "        )", "", "    best_article_id = max(article_scores, key=article_scores.get)  # type: ignore[arg-type]", "    best_article_score = article_scores[best_article_id]", "", "    if best_article_score >= web_config.DEDUP_DUPLICATE_THRESHOLD:", "        classification = DeduplicationClassification.DUPLICATE", "    elif best_article_score >= web_config.DEDUP_SYNDICATION_THRESHOLD:", "        classification = DeduplicationClassification.SYNDICATION_CANDIDATE", "    else:", "        classification = DeduplicationClassification.UNIQUE", "", "    # match_target_id is the article whose best chunk becomes best_match. It is the", "    # top-scored candidate for a score-based match; the signal below can retarget", "    # it to a different candidate when it rescues a diluted UNIQUE.", "    match_target_id = best_article_id", "    syndication_signal_info: Optional[Dict[str, Any]] = None", "", "    # Absolute-count syndication signal: rescue same-story/different-chrome copies", "    # whose chrome dilutes coverage below the syndication threshold. Fires only from", "    # the UNIQUE band and only to SYNDICATION_CANDIDATE \u2014 never DUPLICATE \u2014 and", "    # leaves article_score on the top candidate so verifier banding is unaffected.", "    if classification == DeduplicationClassification.UNIQUE:", "        signal = _select_syndication_signal_winner(candidates_map, article_scores)", "        if signal is not None:", "            signal_winner, high_sim_matched_chunks = signal", "            classification = DeduplicationClassification.SYNDICATION_CANDIDATE", "            match_target_id = signal_winner", "            # Both scores are recorded because the signal can retarget the match to", "            # a candidate other than the top-scored one that article_score describes.", "            syndication_signal_info = {", "                \"matched_article_id\": str(signal_winner),", "                \"high_sim_matched_chunks\": high_sim_matched_chunks,", "                \"similarity_threshold\": web_config.DEDUP_SYNDICATION_SIGNAL_SIMILARITY,", "                \"matched_article_score\": round(article_scores.get(signal_winner, 0.0), 6),", "                \"top_candidate_article_score\": round(best_article_score, 6),", "            }", "", "    # Populate best_match + match_info for any matched classification (DUPLICATE", "    # or SYNDICATION_CANDIDATE). L2 needs best_match on syndication so the", "    # syndication grouper can attach via best_match.article_id.", "    best_match: Optional[ArticleChunk] = None", "    match_info: Dict[str, Any] = {}", "    matched_article_score: Optional[float] = None", "", "    if classification in (", "        DeduplicationClassification.DUPLICATE,", "        DeduplicationClassification.SYNDICATION_CANDIDATE,", "    ):", "        best_chunk_entry = max(candidates_map[match_target_id].items(), key=lambda item: item[1][0])", "        incoming_chunk_idx = best_chunk_entry[0]", "        _best_similarity, best_matched_chunk = best_chunk_entry[1]", "        best_match = best_matched_chunk", "        # Scores the article best_match points at, not the top-scored one \u2014 equal", "        # to best_article_score unless the signal above retargeted the match.", "        matched_article_score = article_scores.get(match_target_id, best_article_score)", "", "        incoming_text_by_index = {c.chunk_index: c.chunk_text for c in chunks}", "        match_info = {", "            \"matched_chunk_index\": best_matched_chunk.chunk_index,", "            \"incoming_chunk_index\": incoming_chunk_idx,", "            \"matched_text\": best_matched_chunk.chunk_text,", "            \"incoming_text\": incoming_text_by_index.get(incoming_chunk_idx, \"\"),", "        }", "        if syndication_signal_info is not None:", "            match_info[\"syndication_signal\"] = syndication_signal_info", "", "    return DeduplicationResult(", "        classification=classification,", "        best_match=best_match,", "        article_score=best_article_score,", "        match_info=match_info,", "        candidates=candidates,", "        matched_article_score=matched_article_score,", "    )", "", "", "async def deduplicate_article(", "    db: AsyncSession,", "    chunk_vectors: ChunkVectors,", "    *,", "    exclude_article_id: Optional[UUID] = None,", "    similarity_as_of: Optional[datetime] = None,", ") -> DeduplicationResult:", "    \"\"\"Article-level dedup against existing chunks. 3-tier classification by", "    ``article_score = coverage * avg_similarity`` with symmetric coverage", "    (``matched_chunks / max(incoming_total, existing_total)``); thresholds in", "    ``web_extraction/config/config.py``.", "", "    Non-obvious mechanics:", "", "    - Chunk similarities below ``DEDUP_FLOOR_THRESHOLD`` are dropped before", "      aggregation \u2014 HNSW returns K rows regardless of quality, so without the", "      floor every grazing match would inflate coverage.", "    - When a filter is active (``exclude_article_id`` / ``similarity_as_of``),", "      the txn sets ``hnsw.iterative_scan = relaxed_order`` so the index walker", "      keeps going past LIMIT until K rows pass the WHERE. Without it, top-K", "      can be entirely filtered out and the article falsely classifies UNIQUE.", "    - **Concurrent-write race is unprotected.** Two workers running this", "      function in parallel against near-duplicate articles can both classify", "      UNIQUE because neither's in-flight chunks are visible to the other's", "      ``SELECT``. Both then write canonicals. Convergence is restored", "      downstream by ``attach_article_to_group``, which takes advisory locks", "      on both ``article_id`` and ``matched_article_id`` and merges crossed", "      groups via ``_merge_syndication_groups`` when a divergence is", "      detected (DAT-6369). Reader-facing queries therefore see one group", "      rather than two unrelated articles, even when both workers wrote", "      canonicals concurrently. Locking here would need a partition key", "      that is exactly what dedup computes \u2014 chicken-and-egg \u2014 so we", "      accept the race and rely on the attach-time merge. Practically rare", "      for L3 (human-paced); occasional for L2 during hot-news bursts.", "", "    Note: this function is intentionally date-agnostic. Time-window policy", "    (the boilerplate defense against template-driven false syndication", "    matches) is applied post-aggregation by the L2 classification chain in", "    ``classify_layer_two_article``, where it can target the SYNDICATION_CANDIDATE", "    classification specifically without forcing high-confidence duplicates", "    to fall through.", "", "    :param db: The datalake database session to use for querying.", "    :type db: AsyncSession", "    :param chunk_vectors: List of chunk vectors with embeddings and text.", "    :type chunk_vectors: ChunkVectors", "    :param exclude_article_id: Optional article id to exclude from candidate", "        matching. Used by retry paths to prevent self-match against chunks that", "        a prior attempt already wrote for the article being deduped.", "    :type exclude_article_id: Optional[UUID]", "    :param similarity_as_of: Optional cutoff timestamp; only chunks with", "        ``created_at <= similarity_as_of`` are considered candidates. Used by", "        L2 retry replay so classification cannot drift due to chunks ingested", "        after the original attempt.", "    :type similarity_as_of: Optional[datetime]", "    :returns: A DeduplicationResult with classification, score, best match, and match info.", "    :rtype: DeduplicationResult", "", "    :raises WebExtractionDataError: If no article chunks are provided.", "    :raises DatabaseReadException: If there is an error querying the database.", "    \"\"\"", "    try:", "        chunks = chunk_vectors.chunks", "        if not chunks:", "            raise WebExtractionDataError(\"No article chunk vectors provided for deduplication\")", "", "        total_incoming_chunks = len(chunks)", "        top_k = web_config.DEDUP_TOP_K", "        filters_active = exclude_article_id is not None or similarity_as_of is not None", "", "        # 1). build the per-chunk halfvec ANN query. Both sides of the cosine", "        # operator must cast to halfvec for the HNSW expression index on", "        # (embedding::halfvec(3072)) to be used. When filters are active we", "        # also turn on iterative_scan so the HNSW walker keeps going past", "        # LIMIT until enough rows pass the WHERE filter (otherwise top-K can", "        # be filled by rows the filter rejects and we lose the true nearest", "        # passing match).", "        where_clauses: List[str] = []", "        if exclude_article_id is not None:", "            where_clauses.append(\"article_id != CAST(:exclude_article_id AS uuid)\")", "        if similarity_as_of is not None:", "            where_clauses.append(\"created_at <= CAST(:similarity_as_of AS timestamptz)\")", "        where_sql = f\"WHERE {' AND '.join(where_clauses)} \" if where_clauses else \"\"", "        nn_query = text(", "            f\"SELECT id FROM web_extraction.article_chunks \"", "            f\"{where_sql}\"", "            f\"ORDER BY (embedding::halfvec(3072)) <=> (:qvec)::halfvec(3072) \"", "            f\"LIMIT :top_k\"", "        )", "        if filters_active:", "            # SET LOCAL is transaction-scoped; safe to leave for the duration", "            # of this dedup call.", "            await db.execute(text(\"SET LOCAL hnsw.iterative_scan = 'relaxed_order'\"))", "", "        all_matched_ids: List[UUID] = []", "        match_sources: Dict[UUID, List[Tuple[int, np.ndarray, str]]] = defaultdict(list)", "", "        for chunk in chunks:", "            # Convert + normalize the incoming embedding once per chunk. The same", "            # array reference is shared across all K source entries below, so the", "            # inner similarity loop in _build_candidates_map does no redundant", "            # list\u2192array conversion and no re-normalization per candidate.", "            incoming_vec = _unit_normalize(np.asarray(chunk.embedding, dtype=float))", "            bind_params: Dict[str, Any] = {\"qvec\": str(chunk.embedding), \"top_k\": top_k}", "            if exclude_article_id is not None:", "                bind_params[\"exclude_article_id\"] = str(exclude_article_id)", "            if similarity_as_of is not None:", "                bind_params[\"similarity_as_of\"] = similarity_as_of", "            result = await db.execute(nn_query.bindparams(**bind_params))", "            rows = result.all()", "            for row in rows:", "                chunk_id = row[0]", "                all_matched_ids.append(chunk_id)", "                match_sources[chunk_id].append((chunk.chunk_index, incoming_vec, chunk.chunk_text))", "", "        # 2). bail early if no matches", "        if not all_matched_ids:", "            return DeduplicationResult(", "                classification=DeduplicationClassification.UNIQUE,", "                best_match=None,", "                article_score=0.0,", "                match_info={},", "            )", "", "        # 3). batch-load all matched ArticleChunk rows", "        unique_ids = list(set(all_matched_ids))", "        matched_chunks_result = await db.execute(", "            select(ArticleChunk).where(ArticleChunk.id.in_(unique_ids))", "        )", "        matched_chunks_map: Dict[UUID, ArticleChunk] = {", "            c.id: c for c in matched_chunks_result.scalars().all()", "        }", "", "        # 4). compute per-article, per-incoming-chunk best similarities", "        candidates_map = _build_candidates_map(match_sources, matched_chunks_map)", "", "        # 5). fetch total chunk counts for each candidate article so coverage", "        # can use a symmetric denominator (max of incoming vs existing chunk", "        # counts). One-directional coverage misclassifies short incoming", "        # articles as DUPLICATE when they happen to fully match a fragment", "        # of a longer existing article.", "        article_chunk_counts: Dict[UUID, int] = {}", "        if candidates_map:", "            counts_result = await db.execute(", "                select(ArticleChunk.article_id, func.count(ArticleChunk.id))", "                .where(ArticleChunk.article_id.in_(list(candidates_map.keys())))", "                .group_by(ArticleChunk.article_id)", "            )", "            article_chunk_counts = {row[0]: row[1] for row in counts_result.all()}", "", "        # 6). compute article-level scores", "        article_scores: Dict[UUID, float] = {}", "        for article_id, chunk_matches in candidates_map.items():", "            matched_count = len(chunk_matches)", "            existing_count = article_chunk_counts.get(article_id, matched_count)", "            coverage = matched_count / max(total_incoming_chunks, existing_count)", "            avg_similarity = sum(s for s, _ in chunk_matches.values()) / matched_count", "            article_scores[article_id] = coverage * avg_similarity", "", "        # 7). build result + emit a structured decision log so the", "        # article_score distribution is observable per environment. Use this", "        # to validate whether DEDUP_TOP_K is wide enough: if score histograms", "        # are bimodal near the duplicate threshold or coverage clusters at", "        # fractional values, K is too narrow.", "        result = _build_dedup_result(candidates_map, article_scores, chunks)", "        winner_article_id = result.best_match.article_id if result.best_match else None", "        logger.info(", "            \"Article dedup classified\",", "            classification=result.classification.value,", "            article_score=round(result.article_score, 4),", "            incoming_chunk_count=total_incoming_chunks,", "            matched_chunk_count=(", "                len(candidates_map[winner_article_id]) if winner_article_id else 0", "            ),", "            existing_chunk_count=(", "                article_chunk_counts.get(winner_article_id, 0) if winner_article_id else 0", "            ),", "            candidate_article_count=len(candidates_map),", "            top_k=top_k,", "            excluded_article_id=str(exclude_article_id) if exclude_article_id else None,", "        )", "        return result", "", "    except (WebExtractionDataError, DatabaseReadException):", "        raise", "    except Exception as e:", "        raise DatabaseReadException(", "            f\"Failed to retrieve best match(es) for article chunk (caused by >>> {e!r})\",", "        ) from e", "", "", "async def upsert_duplicate_article(", "    db: AsyncSession,", "    activity_id: UUID,", "    best_match: ArticleChunk,", "    similarity_score: float,", "    match_info: Dict[str, Any],", "    article_type: ArticleType,", "    content: str,", "    article_url: Optional[str] = None,", "    response_id: Optional[UUID] = None,", "    manual_upload_account_id: Optional[UUID] = None,", ") -> Tuple[UUID, UUID]:", "    \"\"\"Writes a duplicate article record to `web_extraction.duplicated_articles`.", "", "    :param db: Datalake database session", "    :type db: AsyncSession", "    :param activity_id: The UUID of the associated activity", "    :type activity_id: UUID", "    :param best_match: The best matching article chunk found during deduplication.", "    :type best_match: ArticleChunk", "    :param similarity_score: The similarity score of the best match.", "    :type similarity_score: float", "    :param match_info: Additional information about the match.", "    :type match_info: Dict[str, Any]", "    :param article_type: The type of article being processed.", "    :type article_type: ArticleType", "    :param content: The content of the article being processed.", "    :type content: str", "    :param article_url: The article URL being processed (required for non-manual uploads).", "    :type article_url: Optional[str]", "    :param response_id: The response ID from `web_extraction.response.id`.", "    :type response_id: Optional[UUID]", "    :param manual_upload_account_id: The account ID for manual uploads (required for MANUAL_UPLOAD article type).", "    :type manual_upload_account_id: Optional[UUID]", "", "    :returns: A tuple containing the ID of the matched article and the ID of the newly created duplicate article record.", "    :rtype: Tuple[UUID, UUID]", "", "    :raises DatabaseWriteException: If there is an error writing to `web_extraction.duplicated_articles`.", "    :raises DatabaseCommitException: If there is an error committing the DB transaction.", "    \"\"\"", "    # 1). validate inputs", "    if article_type != ArticleType.MANUAL_UPLOAD and (article_url is None or response_id is None):", "        raise WebExtractionDataError(", "            f\"article and response_id must be provided for non-MANUAL_UPLOAD article types; \"", "            f\"received article={best_match.article_id}, response_id={response_id}\"", "        )", "    elif article_type == ArticleType.MANUAL_UPLOAD and manual_upload_account_id is None:", "        raise WebExtractionDataError(", "            f\"manual_upload_account_id must be provided for MANUAL_UPLOAD article type; \"", "            f\"article_id={best_match.article_id}\"", "        )", "", "    # (a). prepare fields", "    matched_article_id: UUID = best_match.article_id", "    duplicate_values = {", "        \"similarity_score\": similarity_score,", "        \"chunk_match_info\": match_info,", "        \"article_type\": article_type,", "        \"matched_article_id\": matched_article_id,", "        \"response_id\": response_id,", "        \"manual_upload_account_id\": manual_upload_account_id,", "        \"content\": content,", "        \"article_url\": (normalize_url(str(article_url)) or str(article_url))", "        if article_url", "        else None,", "    }", "    conflict_constraint = (", "        \"uq_webex_duplicated_articles_manual_upload_account\"", "        if article_type == ArticleType.MANUAL_UPLOAD", "        else \"uq_webex_duplicated_articles_response\"", "    )", "", "    duplicated_article_id: Optional[UUID] = None", "    try:", "        insert_stmt = insert(DuplicatedArticle).values(duplicate_values)", "        stmt = insert_stmt.on_conflict_do_update(", "            constraint=conflict_constraint,", "            set_={", "                \"matched_article_id\": insert_stmt.excluded.matched_article_id,", "                \"similarity_score\": insert_stmt.excluded.similarity_score,", "                \"chunk_match_info\": insert_stmt.excluded.chunk_match_info,", "                \"article_type\": insert_stmt.excluded.article_type,", "                \"response_id\": insert_stmt.excluded.response_id,", "                \"manual_upload_account_id\": insert_stmt.excluded.manual_upload_account_id,", "                \"content\": insert_stmt.excluded.content,", "                \"article_url\": insert_stmt.excluded.article_url,", "                \"updated_at\": func.now(),", "            },", "        ).returning(DuplicatedArticle.id)", "        duplicated_article_id = (await db.execute(stmt)).scalar_one()", "    except DatabaseWriteException:", "        raise", "    except Exception as e:", "        raise DatabaseWriteException(", "            f\"Failed to upsert DuplicatedArticle row for {article_type} (caused by >>> {e!r})\",", "            response_id=response_id,", "            matched_article_id=matched_article_id,", "            manual_upload_account_id=manual_upload_account_id,", "            conflict_constraint=conflict_constraint,", "        ) from e", "", "    try:", "        await db.commit()", "    except Exception as e:", "        try:", "            await db.rollback()", "        except Exception:", "            pass", "        raise DatabaseCommitException(", "            f\"Failed to commit DuplicatedArticle row for {article_type} (caused by >>> {e!r})\",", "            response_id=response_id,", "            matched_article_id=matched_article_id,", "            manual_upload_account_id=manual_upload_account_id,", "            conflict_constraint=conflict_constraint,", "        ) from e", "", "    logger.info(", "        \"Duplicate article written\",", "        duplicated_article_id=str(duplicated_article_id),", "        activity_id=str(activity_id),", "        matched_article_id=str(matched_article_id),", "        similarity_score=f\"{similarity_score:.4f}\",", "    )", "", "    assert duplicated_article_id is not None, \"duplicated_article_id unexpectedly None after upsert\"", "    return matched_article_id, duplicated_article_id", "", "", "async def upsert_zyte_article(", "    db: AsyncSession,", "    article: ArticleSchema,", "    content: str,", "    response_id: UUID,", "    activity_id: UUID,", "    chunk_vectors: ChunkVectors,", "    *,", "    feed_id: Optional[UUID] = None,", ") -> UUID:", "    \"\"\"Idempotently write an Article, ZyteArticle, and related chunks in a single transaction.", "", "    On retry, recovers the existing article_id from the ZyteArticle row (anchored by the", "    response_id unique constraint) instead of creating an orphaned Article.", "", "    :param db: Datalake database session", "    :type db: AsyncSession", "    :param article: The article object being processed.", "    :type article: ArticleSchema", "    :param content: Markdown-formatted article content to store.", "    :type content: str", "    :param response_id: The response ID from `web_extraction.response.id`.", "    :type response_id: UUID", "    :param activity_id: The activity ID for logging purposes.", "    :type activity_id: UUID", "    :param chunk_vectors: List of chunk vectors with embeddings and text", "    :type chunk_vectors: ChunkVectors", "    :param feed_id: The originating feed's id, set on the article only on first", "        run. Forwarded from the L2 pipeline; not used on the recovery branch.", "    :type feed_id: Optional[UUID]", "", "    :returns: The article_id (stable across retries for the same response_id).", "    :rtype: UUID", "", "    :raises DatabaseWriteException: If there is an error writing rows.", "    :raises DatabaseCommitException: If there is an error committing the DB transaction.", "    \"\"\"", "    # 1). recovery: check if a ZyteArticle already exists for this response_id", "    # NOTE: If two workers process the same response_id concurrently (requires SQS", "    # visibility timeout expiry), both may pass this check before either commits.", "    # The losing worker creates an orphan Article row, but the ZyteArticle upsert's", "    # RETURNING clause detects the mismatch and corrects article_id downstream.", "    try:", "        existing = (", "            await db.execute(", "                select(ZyteArticle.article_id).where(ZyteArticle.response_id == response_id)", "            )", "        ).scalar_one_or_none()", "    except Exception as e:", "        raise DatabaseReadException(", "            f\"Failed to query existing ZyteArticle by response_id (caused by >>> {e!r})\",", "            response_id=response_id,", "        ) from e", "", "    if existing is not None:", "        logger.info(", "            \"ZyteArticle already exists for response_id; recovering article_id\",", "            article_id=str(existing),", "            response_id=str(response_id),", "            activity_id=str(activity_id),", "        )", "        return existing", "", "    # 2). first run: create Article row", "    article_row = Article(feed_id=feed_id)", "    try:", "        db.add(article_row)", "        await db.flush()", "    except Exception as e:", "        raise DatabaseWriteException(", "            f\"Failed to create Article row (caused by >>> {e!r})\",", "            response_id=response_id,", "        ) from e", "", "    article_id = article_row.id", "", "    # 3). write ZyteArticle + ArticleChunks + metadata in same transaction", "    zyte_values = {", "        \"article_id\": article_id,", "        \"response_id\": response_id,", "        \"content\": content,", "        \"article_url\": normalize_url(str(article.article_data.url))", "        or str(article.article_data.url),", "        \"article_title\": article.article_data.headline,", "        \"meta_data\": {", "            \"headline\": article.article_data.headline,", "            \"authors\": [name for name in article.article_data.authors]", "            if article.article_data.authors", "            else None,", "            \"language\": article.article_data.in_language,", "            \"main_image_url\": article.article_data.main_image,", "            \"extraction_probability\": article.article_data.extraction_probability,", "            # Same setting the landing-page gate passed, so the stored verdict is", "            # the one that was actually acted on rather than a second opinion.", "            \"is_article_permalink\": is_article_permalink(", "                str(article.article_data.url),", "                enforced_media_are_indexes=web_config.MEDIA_CONTAINER_FILTER_ENFORCE,", "            ),", "        },", "        \"date_published\": article.article_data.date_published,", "        \"date_published_raw\": article.article_data.date_published_raw,", "        \"date_published_source\": article.article_data.date_published_source,", "    }", "    chunk_values = [", "        {", "            \"article_id\": article_id,", "            \"chunk_index\": chunk.chunk_index,", "            \"chunk_text\": chunk.chunk_text,", "            \"embedding\": chunk.embedding,", "        }", "        for chunk in chunk_vectors.chunks", "    ]", "    try:", "        zyte_insert = insert(ZyteArticle).values(zyte_values)", "        # The date trio moves together: a NULL date from a concurrent retry keeps the", "        # stored date, source and raw text, so a NULL never clobbers a stored date.", "        incoming_date_is_null = zyte_insert.excluded.date_published.is_(None)", "        zyte_stmt = zyte_insert.on_conflict_do_update(", "            constraint=\"zyte_articles_response_id_key\",", "            set_={", "                \"content\": zyte_insert.excluded.content,", "                \"article_url\": zyte_insert.excluded.article_url,", "                \"article_title\": zyte_insert.excluded.article_title,", "                \"meta\": zyte_insert.excluded[\"meta\"],", "                \"date_published\": case(", "                    (incoming_date_is_null, ZyteArticle.date_published),", "                    else_=zyte_insert.excluded.date_published,", "                ),", "                \"date_published_source\": case(", "                    (incoming_date_is_null, ZyteArticle.date_published_source),", "                    else_=zyte_insert.excluded.date_published_source,", "                ),", "                \"date_published_raw\": case(", "                    (incoming_date_is_null, ZyteArticle.date_published_raw),", "                    else_=zyte_insert.excluded.date_published_raw,", "                ),", "                \"updated_at\": func.now(),", "            },", "        ).returning(ZyteArticle.id, ZyteArticle.article_id)", "        zyte_article_id, resolved_article_id = (await db.execute(zyte_stmt)).one()", "", "        # If another consumer won the race, use their article_id", "        if resolved_article_id != article_id:", "            logger.warning(", "                \"ZyteArticle upsert resolved to a different article_id; \"", "                \"another consumer won the race \u2014 using winner's article_id\",", "                created_article_id=str(article_id),", "                resolved_article_id=str(resolved_article_id),", "                response_id=str(response_id),", "                activity_id=str(activity_id),", "            )", "            article_id = resolved_article_id", "            for cv in chunk_values:", "                cv[\"article_id\"] = article_id", "", "        chunk_count = await upsert_article_chunks(", "            db=db,", "            article_id=article_id,", "            chunk_values=chunk_values,", "        )", "", "        # 4). update article row metadata", "        article_row = await db.get(Article, article_id)", "        if article_row is None:", "            raise DatabaseReadException(", "                f\"Article with ID {article_id} not found when attempting to add metadata\",", "            )", "", "        # Image state lives in the `web_extraction.article_images` table and the", "        # `articles.images_processed_at` sentinel column, owned by image_service.", "        # Layer two only writes the zyte_articles linkage into JSONB.", "        metadata = dict(article_row.meta_data or {})", "        metadata[\"zyte_articles.id\"] = str(zyte_article_id)", "        article_row.meta_data = metadata", "        await db.flush()", "    except Exception as e:", "        raise DatabaseWriteException(", "            f\"Failed to write ZyteArticle/ArticleChunk rows or update metadata (caused by >>> {e!r})\",", "            response_id=response_id,", "            article_id=article_id,", "        ) from e", "", "    # 5). commit", "    try:", "        await db.commit()", "    except Exception as e:", "        raise DatabaseCommitException(", "            f\"Failed to commit rows (caused by >>> {e!r})\",", "            response_id=response_id,", "            article_id=article_id,", "        ) from e", "", "    logger.info(", "        \"Zyte article written\",", "        zyte_article_id=str(zyte_article_id),", "        article_id=str(article_id),", "        activity_id=str(activity_id),", "        chunk_rows=chunk_count,", "    )", "", "    return article_id", "", "", "async def get_existing_layer_two_response(", "    db: AsyncSession, activity_id: UUID", ") -> Optional[WebExtractionResponse]:", "    \"\"\"Return an existing layer-two response row for this activity, if any.", "", "    :param db: The datalake database session to use for querying.", "    :type db: AsyncSession", "    :param activity_id: The activity ID from ``web_extraction.activity.id``.", "    :type activity_id: UUID", "", "    :returns: The existing response row, or ``None`` if no prior response exists.", "    :rtype: Optional[WebExtractionResponse]", "    \"\"\"", "    result = await db.execute(", "        select(WebExtractionResponse).where(", "            WebExtractionResponse.layer_two_activity_id == activity_id", "        )", "    )", "    return result.scalar_one_or_none()", "", "", "async def read_response_created_at(db: AsyncSession, response_id: UUID) -> datetime:", "    \"\"\"Read the persisted ``responses.created_at`` for a just-written response row.", "", "    The fresh path's scrape time, so it matches what a replay of the same response", "    reads from ``existing_response.created_at``.", "", "    :param db: The datalake database session to use for querying.", "    :type db: AsyncSession", "    :param response_id: The ``web_extraction.responses`` row id.", "    :type response_id: UUID", "    :return: The row's ``created_at``, labelled UTC when naive.", "    :rtype: datetime", "    :raises DatabaseReadException: If the row cannot be read.", "    \"\"\"", "    try:", "        created_at = (", "            await db.execute(", "                select(WebExtractionResponse.created_at).where(", "                    WebExtractionResponse.id == response_id", "                )", "            )", "        ).scalar_one()", "    except Exception as e:", "        raise DatabaseReadException(", "            f\"Failed to read responses.created_at (caused by >>> {e!r})\",", "            response_id=str(response_id),", "        ) from e", "    return as_utc(created_at)"], "blocks": [{"start": 1, "end": 59, "label": "Imports and module setup"}, {"start": 60, "end": 80, "label": "def _unit_normalize"}, {"start": 81, "end": 152, "label": "def embed_article_chunks"}, {"start": 153, "end": 160, "label": "class DeduplicationClassification"}, {"start": 161, "end": 184, "label": "class CandidateMatch"}, {"start": 185, "end": 224, "label": "class DeduplicationResult"}, {"start": 225, "end": 235, "label": "DeduplicationResult.__post_init__"}, {"start": 236, "end": 287, "label": "def _build_candidates_map"}, {"start": 288, "end": 314, "label": "def _high_sim_matched_chunk_count"}, {"start": 315, "end": 361, "label": "def _select_syndication_signal_winner"}, {"start": 362, "end": 389, "label": "def _build_candidate_matches"}, {"start": 390, "end": 499, "label": "def _build_dedup_result"}, {"start": 500, "end": 690, "label": "def deduplicate_article"}, {"start": 691, "end": 819, "label": "def upsert_duplicate_article"}, {"start": 820, "end": 1022, "label": "def upsert_zyte_article"}, {"start": 1023, "end": 1043, "label": "def get_existing_layer_two_response"}, {"start": 1044, "end": 1071, "label": "def read_response_created_at"}], "lineCount": 1071, "sha256": "bc95ba44571d068eba8e1102bf85c66416be254f5cefd80bd37ab53d4d47b9a8", "endsWithNewline": true});
